//! Corpus manifest: paths + labels. Hashed so calibrations are reproducible.

use serde::{Deserialize, Serialize};

/// Label for one corpus entry.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "kind", rename_all = "snake_case")]
pub enum Label {
    /// Real, from a named source class (`phone`, `dslr`, `scan`, `screenshot`).
    Real { source: String },
    /// Generated by a named generator.
    Generated { generator: String },
}

/// One entry.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Entry {
    /// Path relative to the manifest.
    pub path: String,
    /// Label.
    pub label: Label,
}

/// The manifest file.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Corpus {
    /// Corpus id.
    pub id: String,
    /// Entries.
    pub entries: Vec<Entry>,
}
